def next(self):
    if self._stop_iteration:
        raise StopIteration
    elif self._has_saved:
        self._has_saved = False
        # XXX: This keeps a reference to the returned object into
        # `self._saved` until that attribute is overwritten.
        return self._saved
    else:
        return self._generator.next()

